```python
import numpy as np
import pandas as pd

submission_code = f"""
import numpy as np
import pandas as pd

A = {coef_quad[0]!r}
B = {coef_quad[1]!r}
C = {coef_quad[2]!r}

def model(regime, n, seed):
    rng = np.random.default_rng(seed)
    speed = float(regime.config.get("speed", 1.0))
    lam = A * speed * speed + B * speed + C
    if lam < 1e-9:
        lam = 1e-9
    y = rng.poisson(lam, size=int(n))
    return pd.DataFrame({{"unit_id": np.arange(int(n), dtype=int), "y": y.astype(int)}})
"""

# Local smoke test
ns = {}
exec(submission_code, ns)
