    def __init__(self, speed=None):
        self.config = {} if speed is None else {"speed": speed}
        self.context = {}

for s in [0.8, 1.0, 1.28, 1.4, None]:
    df = ns["model"](DummyRegime(s), 5, 123)
    print("speed", s, "shape", df.shape, "cols", list(df.columns))
    print(df.head())
